"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["42006"],{50810(e){e.exports=JSON.parse('{"id":"FIN-1057","slug":"accounting-fraud","term":"Accounting Fraud","also_known_as":[],"difficulty":"Advanced","definition":"Accounting fraud is the deliberate manipulation of a company\'s financial statements to mislead investors, lenders, regulators or others about its financial performance or position.","explanation":["Accounting fraud can take many forms. Common methods include recording fake revenue or recognising revenue too early, hiding liabilities off the balance sheet, overstating assets such as inventory or receivables, understating expenses by capitalizing them, manipulating estimates and reserves, and concealing related-party transactions.","Motives often include meeting earnings targets, supporting the share price, earning bonuses, meeting loan conditions or hiding losses.","Major corporate failures, such as Enron and WorldCom in the early 2000s and Wirecard in 2020, involved accounting fraud. At WorldCom, billions of dollars of ordinary operating expenses were wrongly recorded as capital assets, inflating profits.","Accounting fraud often leads to criminal charges, large fines, restatements, bankruptcy and heavy losses for investors and employees. Safeguards include internal controls, independent audit committees, external audits, whistleblower protections and regulations such as the Sarbanes-Oxley Act in the United States. Warning signs include profits growing much faster than cash flow, frequent changes in accounting policies and unusual transactions near period-ends."],"note":"","total":1725,"prev":{"slug":"accounting-estimate","term":"Accounting Estimate"},"next":{"slug":"accounting-policy","term":"Accounting Policy"}}')}}]);